// local search, which AGENTS.md prefers on permutations ("It often beats a GA on
// permutations"), with its defaults: 1 neighbor per step and the acceptance NotWorse (hill
// climbing across plateaus); the neighbor operator, required, is a swap
let build = |seed| {
    LocalSearch::builder(Permutation::new(size)?)
        .neighbor(SwapMutation::new())
        .minimize()
        .seed(seed)
        .build()
};

|budget| {
    restarts(seed, |run_seed| {
        let hill_climb = HillClimb::builder()
            .with_genotype(nqueens_genotype(args.size))
            .with_variant(HillClimbVariant::Stochastic)
            .with_max_stale_generations(10000)
            .with_fitness(NQueens(budget.clone()))
            .with_fitness_ordering(FitnessOrdering::Minimize)
            .with_target_fitness_score(0)
            .with_replace_on_equal_fitness(true)
            .with_abort_flag(budget.abort_flag.clone())
            .with_rng_seed_from_u64(run_seed)
            .with_reporter(Generations::new(budget))
            .call()
            .unwrap();
        let score = hill_climb.best_fitness_score();
        let conclusive =
            score == Some(0) || (budget.aborted() && !budget.resume_after_stall());
        (
            hill_climb.best_genes(),
            score,
            conclusive,
            hill_climb.state.current_generation,
        )
    })
},

fn nqueens_genotype(size: usize) -> UniqueGenotype<u8> {
    assert!(size <= 256, "nqueens size must be <= 256 for u8 genes");
    UniqueGenotype::builder()
        .with_allele_list((0..size).map(|v| v as u8).collect())
        .build()
        .unwrap()
}

class PermutationDuplicateElimination(ElementwiseDuplicateElimination):
    """Two random-key vectors are duplicates if they decode to the same permutation, as in
    docs/source/algorithms/soo/brkga.md."""

    def is_equal(self, a, b):
        return a.get("hash") == b.get("hash")


def decode_keys(X):
    """BRKGA's decoding of random keys to a permutation: their order (docs/source/algorithms/soo/brkga.md)."""
    return np.argsort(X, axis=1)

def flowshop_convergence():
    """The termination of the flowshop example (docs/source/customization/permutation.md),
    DefaultSingleObjectiveTermination(period=50, n_max_gen=10000), without its generation limit:
    xtol 1e-8 and ftol 1e-6, each over a window of 50 generations."""
    return DefaultSingleObjectiveTermination(period=50, n_max_gen=math.inf, n_max_evals=math.inf)

let build = |budget: Arc<Budget>| {
    // radiate's permutation example (examples/rust/TSP, lines 13-19): PermutationCodec,
    // population 250, minimizing, the other engine defaults (roulette offspring
    // selection, tournament of 3 for the survivors). radiate's own N-Queens example
    // (examples/rust/nqueens) evolves integers with row conflicts in the fitness, not a
    // permutation, so it doesn't apply here.
    let builder = GeneticEngine::builder()
        .codec(PermutationCodec::new((0..size).collect()))
        .raw_fitness_fn(move |genotype: &Genotype<PermutationChromosome<usize>>| {
            let genes = genotype[0].as_slice();
            budget.record(nqueens(genes.iter().map(|gene| *gene.allele())), || {
                genes.iter().map(|gene| *gene.allele() as f64).collect()
            })
        })
        .minimizing()
        .population_size(250);
    match solver {
        // the example as it is: PMXCrossover(0.4) and SwapMutator(0.05)
        "ga" => builder
            .alter(alters!(PMXCrossover::new(0.4), SwapMutator::new(0.05)))
            .build(),
        // the permutation recipe: PMX at 0.5 and Swap (the example's mutator) at 0.01.
        // Shuffle crossover is left out: it swaps genes between the parents position by
        // position, so its children aren't permutations, and the engine replaces them
        // with random ones (radiate-engines-1.3.1/src/steps/filter.rs)
        _ => builder
            .alter(alters!(PMXCrossover::new(0.5), SwapMutator::new(0.01)))
            .build(),
    }
};

