// permutation: moors has no permutation example, no stated preference and no default
// among its permutation operators (docs/user_guide/operators/rust/sampling.md,
// crossover.md, mutation.md): PermutationSampling, OrderCrossover (its one permutation
// crossover), SwapMutation (the mutation its docs describe as exploring "neighboring
// permutations"); the rates are AlgorithmBuilder's
// defaults (crossover 0.9, mutation 0.2: src/algorithms/builder.rs lines 86-89), the
// population and offspring 200 of the docs' real-valued example
// (docs/getting_started/rust/real_valued.md), and exact duplicate removal as in the
// README's discrete example
("nqueens", _) => run!(
    ga!()
        .sampler(PermutationSampling::new())
        .crossover(OrderCrossover::new())
        .mutation(SwapMutation::new())
        .duplicates_cleaner(ExactDuplicatesCleaner::new())
        .constraints_fn(NoConstraints)
        .population_size(200)
        .num_offsprings(200)
        .crossover_rate(0.9)
        .mutation_rate(0.2)
),

// moors' single-objective GA: AlgorithmBuilder with RankSelection (binary tournament on
// the fitness rank) and FitnessSurvival (the best of parents and offspring survive). These
// two are what pymoors' GeneticAlgorithmSOO fixes (pymoors/src/algorithms/soo/mod.rs
// lines 82-88) and what moors' single-objective test uses (moors/tests/test_ga_soo.rs
// lines 23-28); the survival and selection of a custom algorithm are the user's choice
// (docs/user_guide/algorithms/custom/rust-custom.md).
macro_rules! ga {
    () => {
        AlgorithmBuilder::default()
            .selector(RankSelection)
            .survivor(FitnessSurvival)
    };
}

// builds and runs one moors GA; every generation evaluates at least one row, so the
// budget ends the run before this iteration count. The best of its final population
// (FitnessSurvival keeps the best of parents and offspring, so it's the attempt's best)
// is kept if it's better than the other attempts'.
macro_rules! run {
    ($builder:expr) => {{
        let mut algorithm = $builder
            .fitness_fn(fitness)
            .num_vars(size)
            .controller(budget)
            .num_iterations(args.max_evaluations.max(1))
            .seed(run_seed)
            .verbose(false)
            .build()
            .expect("valid moors configuration");
        algorithm.run().expect("moors run");
        let population = algorithm.population.expect("population after run");
        let (row, &fitness) = population
            .fitness
            .iter()
            .enumerate()
            .min_by(|a, b| a.1.total_cmp(b.1))
            .expect("a population");
        if best.as_ref().is_none_or(|(best, _)| fitness < *best) {
            best = Some((fitness, population.genes.row(row).to_vec()));
        }
    }};
}

// The manual's "Traveling salesman" example (section 6.5), Jenetics' permutation
// example: Codecs.ofPermutation, population 500, maximal age 11, SwapMutator(0.2),
// PartiallyMatchedCrossover(0.35), the other settings the engine defaults
// (TournamentSelector(3), 60% offspring). It ends the stream with
// Limits.bySteadyFitness(25), a convergence criterion: an attempt ends after 25
// generations without a better best, and the run restarts (rule 2.2); its
// limit(250) is a budget, lifted. (The delivered program
// jenetics.example/TravelingSalesman.java sets other values; see the page.)
solvers.add(new Solver("ga", (budget, seed) -> evolve(
    Engine.builder((int[] order) -> {
                double value = nqueens(order);
                if (budget.record(value)) budget.solution = order.clone();
                return value;
            }, Codecs.ofPermutation(size))
        .optimize(Optimize.MINIMUM)
        .maximalPhenotypeAge(11)
        .populationSize(500)
        .alterers(new SwapMutator<>(0.2), new PartiallyMatchedCrossover<>(0.35))
        .executor(Runnable::run)
        .build(),
    budget, 25, seed)));

static <G extends Gene<?, G>, C extends Comparable<? super C>> long evolve(
        Engine<G, C> engine, Budget budget, int steadyGenerations, long seed) {
    long generations = 0;
    for (int restart = 0; ; restart++) {
        if (restart > 0) seed((seed + 1) * 1_000_000 + restart);
        long[] attempt = {0};
        int[] idle = {0};
        // every generation's end, the first of each attempt (its initial population and its
        // first offspring) included: this limit comes first, so it sees every result, also
        // the one that the steady-fitness limit ends the attempt at
        var stream = engine.stream().limit(result -> {
            idle[0] = budget.evaluations == budget.generationEnd ? idle[0] + 1 : 0;
            budget.endGeneration();
            return true;
        });
        if (steadyGenerations > 0) stream = stream.limit(Limits.bySteadyFitness(steadyGenerations));
        stream
            .limit(result -> {
                attempt[0] = result.generation();
                return !budget.done() && idle[0] < STALL_GENERATIONS;
            })
            .forEach(result -> {});
        generations += attempt[0];
        if (budget.done()) return generations;
    }
}

// jmetal-component examples/singleobjective/geneticalgorithm/GeneticAlgorithmTSPExample.java:
// population 100, 100 children, binary tournament, PMXCrossover(0.9),
// PermutationSwapMutation(1 / n), (μ + λ) replacement
solvers.add(new Solver("ga", (budget, seed) -> runComponent(budget, termination ->
    new GeneticAlgorithmBuilder<>("GGA", new NQueensProblem(size, budget), 100, 100,
            new PMXCrossover(0.9), new PermutationSwapMutation<Integer>(1.0 / size))
        .setTermination(termination)
        .build())));

static <S extends Solution<?>> long runComponent(Budget budget,
                                                 Function<Termination, EvolutionaryAlgorithm<S>> build) {
    long[] generations = {0};
    EvolutionaryAlgorithm<S> algorithm = build.apply(status -> {
        budget.endGeneration();
        generations[0]++;
        return false;
    });
    try {
        algorithm.run();
    } catch (Stop stop) {
        // the target, the budget or the time cap
    }
    return generations[0];
}

# the BRKGA docstring (docs/src/algorithms/combinatorial.md, "BRKGA"): random keys in [0, 1]^n
# decoded by sortperm, with the defaults (20 elites, 10 mutants, 70 offspring, bias 0.7)
brkga = function (budget, seed)
    bounds = boxconstraints(lb = zeros(size), ub = ones(size))
    return optimize(
        counted(keys -> nqueens(sortperm(keys)), budget), bounds, BRKGA(; algorithm_kwargs(budget, seed)...);
        logger = generation_logger(budget),
    )
end

void solve_nqueens(const Args &args, long long seed) {
    const int size = args.size;
    const std::function<void(PermutationGA &)> setup = [size](PermutationGA &ga) {
        configure(ga);
        // openGA assist's generated settings, as for OneMax: population 200, crossover_fraction
        // 0.7, mutation_rate 0.2, elite_count 10, best_stall_max 10 (assist/main.js L435-436,
        // L460-465) and openGA's other stall defaults. openGA has no permutation operators and no
        // permutation example, so the usual ones: a random permutation, order crossover (OX1, one
        // child, as openGA's crossover returns one) and a swap of two genes.
        ga.population = 200;
        ga.crossover_fraction = 0.7;
        ga.mutation_rate = 0.2;
        ga.elite_count = 10;
        assist_stall(ga);
        ga.init_genes = [size](Permutation &q, const Rnd01 &rnd01) {
            q.p.resize(size);
            for (int i = 0; i < size; i++) q.p[i] = i;
            for (int i = size - 1; i > 0; i--) std::swap(q.p[i], q.p[random_index(rnd01, i + 1)]);
        };
        ga.eval_solution = [](const Permutation &q, Cost &c) {
            c.cost = nqueens(q.p);
            budget.record(c.cost);
            return true;
        };
        ga.calculate_SO_total_fitness = [](const PermutationGA::thisChromosomeType &X) { return X.middle_costs.cost; };
        ga.SO_report_generation = [](int, const EA::GenerationType<Permutation, Cost> &, const Permutation &) {};
        ga.crossover = [size](const Permutation &a, const Permutation &b, const Rnd01 &rnd01) {
            int first = random_index(rnd01, size), second = random_index(rnd01, size);
            if (first > second) std::swap(first, second);
            Permutation child;
            child.p.assign(size, -1);
            std::vector<char> used(size, 0);
            for (int i = first; i <= second; i++) {
                child.p[i] = a.p[i];
                used[a.p[i]] = 1;
            }
            int position = (second + 1) % size;
            for (int k = 0; k < size; k++) {
                const int gene = b.p[(second + 1 + k) % size];
                if (used[gene]) continue;
                child.p[position] = gene;
                position = (position + 1) % size;
            }
            return child;
        };
        ga.mutate = [size](const Permutation &base, const Rnd01 &rnd01, double) {
            Permutation child = base;
            const int i = random_index(rnd01, size);
            int j = random_index(rnd01, size - 1);
            if (j >= i) j++;
            std::swap(child.p[i], child.p[j]);
            return child;
        };
    };

    const RunResult run = run_ga<PermutationGA>(seed, args.max_evaluations, args.max_seconds, 0.0, setup);
    const std::vector<int> order(run.best_genes.begin(), run.best_genes.end());
    const double best = nqueens(order);
    print_single(args, "ga", seed, run, best, 0, best <= 0.0, true);
}

RunResult run_ga(long long seed, long long max_evaluations, double max_seconds, double target,
                 const std::function<void(GA &)> &setup) {
    start_budget(max_evaluations, max_seconds, target);
    RunResult result{0.0, 0, 0, 0};
    for (long long attempt = 0;; attempt++) {
        GA ga;
        setup(ga);
        seed_ga(ga, attempt_seed(std::uint64_t(seed), std::uint64_t(attempt)));
        long long before = budget.evaluations;
        ga.solve_init();
        result.last_generation = budget.evaluations - before;
        bool converged = false;
        while (!converged && !budget.reached() && !budget.exhausted()) {
            before = budget.evaluations;
            converged = ga.solve_next_generation() != EA::StopReason::Undefined;
            result.last_generation = budget.evaluations - before;
            result.generations++;
        }
        const auto &generation = ga.last_generation;
        const auto &best = generation.chromosomes[generation.best_chromosome_index];
        if (best.total_cost < result.best_cost) {
            result.best_cost = best.total_cost;
            result.best_genes = numbers(best.genes);
        }
        if (budget.reached() || budget.exhausted()) break;
        result.restarts++;
    }
    result.seconds = std::chrono::duration<double>(Clock::now() - budget.start).count();
    return result;
}
